// Get the AI Agent output
const raw = $json.output ?? $json;

// Convert string output to JSON if necessary
let invoice;

if (typeof raw === "string") {
  try {
    invoice = JSON.parse(raw);
  } catch (error) {
    throw new Error("AI Agent output is not valid JSON.");
  }
} else {
  invoice = raw;
}

// Make sure invoice is an object
if (!invoice || typeof invoice !== "object") {
  throw new Error("AI Agent did not return a valid invoice object.");
}

const errors = [];

// Required field checks
if (!invoice.invoice_number) {
  errors.push("Invoice number is missing");
}

if (!invoice.invoice_date) {
  errors.push("Invoice date is missing");
}

if (!invoice.vendor) {
  errors.push("Vendor name is missing");
}

if (
  invoice.total_amount === null ||
  invoice.total_amount === undefined
) {
  errors.push("Total amount is missing");
}

// Calculate subtotal from line items
const calculatedSubtotal = (invoice.items || []).reduce(
  (sum, item) => {
    const quantity = Number(item.quantity) || 0;
    const unitPrice = Number(item.unit_price) || 0;

    return sum + (quantity * unitPrice);
  },
  0
);

// Compare extracted subtotal with calculated subtotal
let subtotalDifference = null;

if (
  invoice.subtotal !== null &&
  invoice.subtotal !== undefined
) {
  subtotalDifference =
    Math.abs(Number(invoice.subtotal) - calculatedSubtotal);
}

// Determine validation status
const calculationValid =
  subtotalDifference === null ||
  subtotalDifference < 0.01;

const validationStatus =
  errors.length === 0 && calculationValid
    ? "Valid"
    : "Needs Review";

// Return validated invoice data
return {
  json: {
    ...invoice,

    calculated_subtotal: Number(
      calculatedSubtotal.toFixed(2)
    ),

    subtotal_difference:
      subtotalDifference !== null
        ? Number(subtotalDifference.toFixed(2))
        : null,

    validation_status: validationStatus,

    validation_errors: errors
  }
};

