const raw = $json.output ?? $json;

// Convert string output to JSON if necessary
let invoice;

if (typeof raw === "string") {
  try {
    invoice = JSON.parse(raw);
  } catch (error) {
    throw new Error("Previous node output is not valid JSON.");
  }
} else {
  invoice = raw;
}

// Make sure invoice is an object
