  throw new Error("Invoice data is not a valid object.");
}

// Build searchable text for expense categorization
const text = [
  invoice.vendor || "",
  invoice.summary || "",
  ...(invoice.items || []).map(
    item => item.description || ""
  )
]
  .join(" ")
  .toLowerCase();

let category = "Other";

// Electronics
